properties.SQL Query:
CREATE TABLE IF NOT EXISTS ${dest_fqn}_delta AS 
SELECT 
    *,
    CURRENT_TIMESTAMP()::TIMESTAMP_NTZ AS SYS_SF_INGESTED_AT
FROM ${dest_fqn}
WHERE FALSE;

properties.defered_merge_sql:
MERGE INTO ${dest_fqn} B
USING (
  SELECT * EXCLUDE (SYS_SF_INGESTED_AT)
  FROM STRM_${dest_fqn}_delta
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ${partition_column} ORDER BY SYS_SF_INGESTED_AT DESC) = 1
) D
ON ${merge_on_expr}
WHEN MATCHED THEN UPDATE ALL BY NAME
WHEN NOT MATCHED THEN INSERT ALL BY NAME;

properties.Script Body:
import groovy.json.JsonSlurper

def flowFile = session.get()
if (!flowFile) return

try {
    def raw = flowFile.getAttribute('MERGE_KEYS') ?: ''
    raw = raw.trim()

    List<String> keys
    if (!raw) {
        throw new Exception("MERGE_KEYS attribute is empty")
    } else if (raw.startsWith('[')) {
        keys = new JsonSlurper().parseText(raw) as List<String>
    } else {
        keys = raw.split(/\s*,\s*/).toList()
    }

    keys = keys.collect { it?.trim() }.findAll { it }

    if (keys.isEmpty()) {
        throw new Exception("MERGE_KEYS resolved to an empty list")
    }

    def q = { s -> '"' + s.replace('"', '""') + '"' }

    def mergeOnExpr = keys.collect { k -> "D.${q(k)} = B.${q(k)}" }.join(' AND ')

    flowFile = session.putAttribute(flowFile, 'merge_on_expr', mergeOnExpr)
    session.transfer(flowFile, REL_SUCCESS)
} catch (Exception e) {
    log.error("Failed to build merge_on_expr", e)
    flowFile = session.putAttribute(flowFile, 'merge_expr_error', e.message ?: 'unknown error')
    session.transfer(flowFile, REL_FAILURE)
}
